-- Rock yard: Star Nursery Las Vegas decorative rock, boulders, sand/soil/gravel and flagstone (retail, Nov 9, 2026).
-- Shared: the items live in Hardscape and also show in Landscape (also_trades).
-- Replaces everything that was in the Hardscape database (pros keep the products they already copied).

ALTER TABLE public.trade_catalog_items ADD COLUMN IF NOT EXISTS also_trades TEXT[] NOT NULL DEFAULT '{}';
CREATE INDEX IF NOT EXISTS trade_catalog_items_also_trades ON public.trade_catalog_items USING GIN (also_trades);

DELETE FROM public.trade_catalog_items WHERE trade = 'hardscape';

ON CONFLICT DO NOTHING;
